      <div style={{ background: "#FFFFFF", color: "var(--ink)", borderRadius: "28px", padding: "34px", display: "flex", flexDirection: "column", gap: "14px" }}><span style={{ width: "56px", height: "56px", borderRadius: "18px", background: "var(--soft)", display: "flex", alignItems: "center", justifyContent: "center" }}><svg width="26" height="26" viewBox="0 0 24 24" fill="none" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{ stroke: "var(--priD)" }}><path d="M3 6h18v15H3zM16 2v4M8 2v4M3 10h18"></path></svg></span><h3 style={{ margin: "0", fontSize: "21px", fontWeight: "700" }}>Bookings are the scoreboard</h3><p style={{ margin: "0", fontSize: "15px", lineHeight: "1.6", color: "var(--muted)" }}>We judge success by appointments on your calendar, not leads in a spreadsheet.</p></div>
